@msig trait FlowStatusDeterminer_supervisorProcess_flowStatusDeterminer_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_flowStatusDeterminer)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_flowStatusDeterminer)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_flowStatusDeterminer)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_flowStatusDeterminer)
  }

  /** helper function to set the values of all input ports.
   * @param decisionReason payload for data port decisionReason
   * @param appliedSnapshot payload for data port appliedSnapshot
   */
  def put_concrete_inputs(decisionReason : Factory_Flow.DecisionReason.Type,
                          appliedSnapshot : Factory_Flow.FlowSnapshot): Unit = {
    put_decisionReason(decisionReason)
    put_appliedSnapshot(appliedSnapshot)
  }


  /** helper function to check FlowStatusDeterminer_supervisorProcess_flowStatusDeterminer's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param flowStatus method that will be called with the value of the outgoing data
   *        port 'flowStatus'.
   */
  def check_concrete_output(flowStatus: Factory_Flow.ProductionFlowStatus.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val flowStatusValue: Factory_Flow.ProductionFlowStatus.Type = get_flowStatus().get
    if(!flowStatus(flowStatusValue)) {
      testFailures = testFailures :+ st"'flowStatus' did not match expected: value of the outgoing data port is ${flowStatusValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_decisionReason(value : Factory_Flow.DecisionReason.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_flowStatusDeterminer.operational_api.decisionReason_Id, Factory_Flow.DecisionReason_Payload(value))
  }

  // setter for in DataPort
  def put_appliedSnapshot(value : Factory_Flow.FlowSnapshot): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_flowStatusDeterminer.operational_api.appliedSnapshot_Id, Factory_Flow.FlowSnapshot_Payload(value))
  }

  // getter for out DataPort
  def get_flowStatus(): Option[Factory_Flow.ProductionFlowStatus.Type] = {
    val value: Option[Factory_Flow.ProductionFlowStatus.Type] = get_flowStatus_payload() match {
      case Some(Factory_Flow.ProductionFlowStatus_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port flowStatus.  Expecting 'Factory_Flow.ProductionFlowStatus_Payload' but received ${v}")
      case _ => None[Factory_Flow.ProductionFlowStatus.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_flowStatus_payload(): Option[Factory_Flow.ProductionFlowStatus_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_flowStatusDeterminer.initialization_api.flowStatus_Id).asInstanceOf[Option[Factory_Flow.ProductionFlowStatus_Payload]]
  }

}
